static void coax_show_t_PS_Loc(const coax_t_PS_Loc *v) {
  fputs("PS_Loc.{", stdout);
  fputs("line = ", stdout); coax_print_int(v->line);
  fputs(", column = ", stdout); coax_print_int(v->column);
  fputs(", offset = ", stdout); coax_print_int(v->offset);
  fputc('}', stdout);
}
static void coax_show_t_PS_Token(const coax_t_PS_Token *v) {
  fputs("PS_Token.{", stdout);
  fputs("kind = ", stdout); coax_print_uint(v->kind);
  fputs(", text = ", stdout); coax_show_string(v->text);
  fputs(", loc = ", stdout); coax_show_t_PS_Loc(&v->loc);
  fputs(", value = ", stdout); coax_print_uint(v->value);
  fputs(", floating = ", stdout); coax_print_float(v->floating, 0);
  fputs(", width = ", stdout); coax_print_int(v->width);
  fputs(", raw_count = ", stdout); coax_print_int(v->raw_count);
  fputc('}', stdout);
}
